function validate([arr, target]) {
  if (arr.length < 1 || arr.length > 100000) return 'arr needs 1 to 10^5 values.';
  if (arr.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each value of arr is a whole number from 1 to 1000.';
  if (!Number.isInteger(target) || target < 1 || target > 100000000) return 'target is a whole number from 1 to 10^8.';
  return null;
}

