function minSumOfLengths(arr, target) {
  const n = arr.length;
  const best = new Array(n).fill(Infinity);
  let answer = Infinity;
  let left = 0;
  let sum = 0;

  for (let right = 0; right < n; right++) {
    sum += arr[right];
    while (sum > target) {
      sum -= arr[left];
      left++;
    }
    if (sum === target) {
      const length = right - left + 1;
      if (left > 0 && best[left - 1] < Infinity) {
        answer = Math.min(answer, best[left - 1] + length);
      }
      best[right] = length;
    }
    if (right > 0) {
      best[right] = Math.min(best[right], best[right - 1]);
    }
  }
  return answer === Infinity ? -1 : answer;
}

