function minSumOfLengths(arr, target) {
  // List every sub-array with the target sum, then try every disjoint pair.
  const windows = [];
  for (let i = 0; i < arr.length; i++) {
    let total = 0;
    for (let j = i; j < arr.length; j++) {
      total += arr[j];
      if (total === target) windows.push([i, j]);
    }
  }
  let result = -1;
  for (const [a, b] of windows) {
    for (const [c, d] of windows) {
      if (b < c) {
        const total = (b - a + 1) + (d - c + 1);
        if (result === -1 || total < result) result = total;
      }
    }
  }
  return result;
}

