function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') {
    const n = 1500 + pick(501);
    const top = rand() < 0.5 ? 5 : 1000;
    const arr = Array.from({ length: n }, () => 1 + pick(top));
    // Use the sum of a random window as the target so at least one window matches.
    const start = pick(n);
    const end = Math.min(n - 1, start + pick(top === 5 ? 40 : 6));
    let target = 0;
    for (let i = start; i <= end; i++) target += arr[i];
    return [arr, target];
  }
  const n = 1 + pick(12);
  const top = rand() < 0.5 ? 3 : 8;
  const arr = Array.from({ length: n }, () => 1 + pick(top));
  const target = 1 + pick(top * 3);
  return [arr, target];
}
